package com.xyz.question_bank_management_system.modules.profile.mapper;
import com.xyz.question_bank_management_system.modules.profile.entity.StudentKnowledgeModelState;import org.apache.ibatis.annotations.*;
@Mapper public interface DimktStateMapper {@Select("SELECT * FROM student_knowledge_model_state WHERE user_id=#{userId} AND course_id=#{courseId} AND status='ACTIVE' LIMIT 1")StudentKnowledgeModelState select(@Param("userId")Long userId,@Param("courseId")Long courseId);@Insert("INSERT INTO student_knowledge_model_state(user_id,course_id,model_version,knowledge_index_version,state_ref,processed_through_seq,status,updated_at) VALUES(#{userId},#{courseId},#{modelVersion},#{knowledgeIndexVersion},#{stateRef},#{processedThroughSeq},#{status},NOW(3)) ON DUPLICATE KEY UPDATE model_version=VALUES(model_version),knowledge_index_version=VALUES(knowledge_index_version),state_ref=VALUES(state_ref),processed_through_seq=VALUES(processed_through_seq),status=VALUES(status),updated_at=NOW(3)")int upsert(StudentKnowledgeModelState v);}
